CREATE TABLE StockItem ( id INTEGER PRIMARY KEY, item_code VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100), qty INTEGER CHECK(qty >= 0), price FLOAT NOT NULL );
CREATE TABLE Student ( id INTEGER PRIMARY KEY, adm_no VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, class_level VARCHAR(20) );
CREATE TABLE FeesLedger ( id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES Student(id), amount FLOAT NOT NULL CHECK(amount > 0), type VARCHAR(20) NOT NULL, description VARCHAR(200), date DATETIME DEFAULT CURRENT_TIMESTAMP );